      "text": "interface:\n  display_name: \"AIDO by SR3H\"\n  short_description: \"Find why AI may overlook a business and test its discoverability\"\n  default_prompt: \"Check my website's AI discoverability, then offer the sourced ten-question sample.\"\n\ndependencies:\n  tools:\n    - type: \"mcp\"\n      value: \"aido-discoverability-check\"\n      description: \"Read-only public website evidence and AIDO research analysis\"\n      transport: \"streamable_http\"\n      url: \"https://mcp.sr3h.uk/mcp\"\n\npolicy:\n  allow_implicit_invocation: true\n"
